import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"套餐、订单与兑换码","description":"","frontmatter":{},"headers":[],"relativePath":"admin/plans-orders.md","filePath":"admin/plans-orders.md","lastUpdated":1788621106000}`),a={name:`admin/plans-orders.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="套餐、订单与兑换码" tabindex="-1">套餐、订单与兑换码 <a class="header-anchor" href="#套餐、订单与兑换码" aria-label="Permalink to “套餐、订单与兑换码”">​</a></h1><h2 id="套餐配置" tabindex="-1">套餐配置 <a class="header-anchor" href="#套餐配置" aria-label="Permalink to “套餐配置”">​</a></h2><p>套餐可定义适用对象、价格、计费周期、邮箱数、域名数、成员数、存储和发信权益。修改已售套餐前，先确认现有订阅是沿用旧权益还是跟随新配置，避免用户权益意外变化。</p><p>免费、个人和企业套餐可以同时存在。隐藏套餐只应停止新购买，不应破坏已有订阅的查询和续期。</p><h2 id="订单" tabindex="-1">订单 <a class="header-anchor" href="#订单" aria-label="Permalink to “订单”">​</a></h2><p>订单管理页用于核对编号、用户或组织、金额、支付方式、状态和回调记录。处理异常订单时按以下顺序：</p><ol><li>核对服务端收到的支付回调与签名验证结果。</li><li>核对支付平台交易号、金额和币种。</li><li>查看钱包流水或订阅权益是否已写入。</li><li>通过幂等处理补偿，避免重复加款或重复开通。</li></ol><p>不要仅根据用户付款截图手工改成已支付。</p><h2 id="钱包流水" tabindex="-1">钱包流水 <a class="header-anchor" href="#钱包流水" aria-label="Permalink to “钱包流水”">​</a></h2><p>余额变化应有对应流水，包含方向、金额、业务来源和关联编号。人工调整必须写明原因和操作人。总余额与流水不一致时先停止继续调整，保存现场并检查事务日志。</p><h2 id="兑换码" tabindex="-1">兑换码 <a class="header-anchor" href="#兑换码" aria-label="Permalink to “兑换码”">​</a></h2><p>创建兑换码时设置权益、有效期、总次数和单用户限制。批量生成后按敏感凭据管理；泄露时立即停用未使用批次。兑换记录应能追溯到用户、时间和获得的权益。</p><h2 id="退款与取消" tabindex="-1">退款与取消 <a class="header-anchor" href="#退款与取消" aria-label="Permalink to “退款与取消”">​</a></h2><p>退款需要同时处理支付平台、订单、钱包或订阅。任何一步失败都应进入可追踪的待处理状态，不能只修改界面显示。</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};